                    <span class="badge-count">${$json.lowStockCount}</span>
                </div>
                <div style="font-size:0.8rem; background:#f1f5f9; padding:6px 14px; border-radius:40px; color:#334155;">
                    <i class="fas fa-truck-fast"></i> Below minimum threshold
                </div>
            </div>

            <!-- TABLE -->
            <div class="inventory-wrapper">
                <table class="stock-table">
                    <thead>
                        <tr>
                            <th><i class="fas fa-cube"></i>&nbsp; Product</th>
                            <th><i class="fas fa-archive"></i>&nbsp; Current Stock</th>
                            <th><i class="fas fa-flag-checkered"></i>&nbsp; Threshold</th>
                            <th><i class="fas fa-bell"></i>&nbsp; Status</th>
                        </tr>
