<script>
    // ------------------------------
    // PRODUCT DATA (simulate your inventory)
    // Change this array to test "no alert" scenario
    // ------------------------------
    const products = [
        { name: "Oil test", stock: 10, threshold: 15 }
        // Add more products: { name: "Hydraulic Fluid", stock: 45, threshold: 15 }
    ];

    const THRESHOLD = 15;  // low-stock threshold

    // Helper: filter low stock products
    function getLowStockItems() {
        return products.filter(p => p.stock <= THRESHOLD);
    }

    // Render low stock table and toggle visibility
    function updateAlertSection() {
        const lowItems = getLowStockItems();
        const container = document.getElementById('lowStockContainer');
        const placeholder = document.getElementById('noAlertPlaceholder');
        const countSpan = document.getElementById('lowStockCount');
        const tableBody = document.getElementById('lowStockTableBody');

        if (lowItems.length === 0) {
            // No alert: hide alert section, show placeholder
            if (container) container.style.display = 'none';
            if (placeholder) placeholder.style.display = 'block';
            return;
        }

        // Show alert section, hide placeholder
        if (container) container.style.display = 'block';
        if (placeholder) placeholder.style.display = 'none';

        // Update badge count
        if (countSpan) countSpan.innerText = lowItems.length;

        // Build table rows
        if (tableBody) {
            tableBody.innerHTML = '';
            lowItems.forEach(item => {
                const row = document.createElement('tr');
                row.innerHTML = `
                    <td class="product-name"><i class="fas fa-cube"></i> <strong>${escapeHtml(item.name)}</strong></td>
                    <td><span class="stock-critical"><i class="fas fa-exclamation-circle"></i> ${item.stock} units</span></td>
                    <td><span class="status-low-badge"><i class="fas fa-bell"></i> LOW STOCK</span></td>
                    <td><button class="btn-reorder" data-product="${escapeHtml(item.name)}" data-stock="${item.stock}"><i class="fas fa-sync-alt"></i> Reorder now</button></td>
                `;
                tableBody.appendChild(row);
            });

            // Attach event listeners to new buttons
            attachReorderEvents();
        }

        // Update footer message with product list
        const alertMsg = document.getElementById('alertMessage');
        if (alertMsg && lowItems.length) {
            const productNames = lowItems.map(i => `"${i.name}"`).join(', ');
            alertMsg.innerHTML = `<strong>⚠️ Immediate action required:</strong> ${productNames} ${lowItems.length === 1 ? 'is' : 'are'} critically low (≤ ${THRESHOLD} units). Please reorder now.`;
        }
    }

    // Simple XSS protection
    function escapeHtml(str) {
        return str.replace(/[&<>]/g, function(m) {
            if (m === '&') return '&amp;';
            if (m === '<') return '&lt;';
            if (m === '>') return '&gt;';
            return m;
        });
    }

    // Toast feedback for reorder actions
    function showReorderFeedback(productName) {
        const toast = document.createElement('div');
        toast.innerText = `📦 Reorder request for ${productName} has been sent to procurement.`;
        toast.style.position = 'fixed';
        toast.style.bottom = '20px';
        toast.style.left = '50%';
        toast.style.transform = 'translateX(-50%)';
        toast.style.backgroundColor = '#1a4d7a';
        toast.style.color = 'white';
        toast.style.padding = '12px 24px';
        toast.style.borderRadius = '60px';
        toast.style.fontWeight = '500';
        toast.style.zIndex = '1000';
        toast.style.boxShadow = '0 10px 20px rgba(0,0,0,0.2)';
        toast.style.fontFamily = "'Inter', sans-serif";
        document.body.appendChild(toast);
        setTimeout(() => {
            toast.style.opacity = '0';
            toast.style.transition = 'opacity 0.3s';
            setTimeout(() => toast.remove(), 400);
        }, 2600);
    }

    function attachReorderEvents() {
        const btns = document.querySelectorAll('.btn-reorder');
        btns.forEach(btn => {
            btn.removeEventListener('click', handleReorderClick);
            btn.addEventListener('click', handleReorderClick);
        });
    }

    function handleReorderClick(e) {
        e.preventDefault();
        const product = e.currentTarget.getAttribute('data-product') || 'product';
        showReorderFeedback(product);
        const originalHtml = e.currentTarget.innerHTML;
        e.currentTarget.innerHTML = '<i class="fas fa-check"></i> Requested';
        e.currentTarget.disabled = true;
        e.currentTarget.style.opacity = '0.6';
        setTimeout(() => {
            e.currentTarget.innerHTML = originalHtml;
            e.currentTarget.disabled = false;
            e.currentTarget.style.opacity = '1';
        }, 2000);
    }

    // Bulk order button
    const bulkBtn = document.getElementById('bulkReorderBtn');
    if (bulkBtn) {
        bulkBtn.addEventListener('click', () => {
            const lowItems = getLowStockItems();
            if (lowItems.length) {
                const names = lowItems.map(i => i.name).join(', ');
                showReorderFeedback(names);
            } else {
                showReorderFeedback('all low stock items');
            }
        });
    }

    // Update date/time
    function updateDateTime() {
        const now = new Date();
        const dateStr = now.toLocaleDateString(undefined, { year: 'numeric', month: 'long', day: 'numeric' });
        const timeStr = now.toLocaleTimeString(undefined, { hour: '2-digit', minute: '2-digit', second: '2-digit' });
        const dateSpan = document.getElementById('liveDateTime');
        const timeSpan = document.getElementById('liveTime');
        if (dateSpan) dateSpan.innerText = dateStr;
        if (timeSpan) timeSpan.innerText = timeStr;
    }
    updateDateTime();
    setInterval(updateDateTime, 1000);

    // Initial render
    updateAlertSection();
</script>
</body>
</html>

